import { GameControls } from "../Controls/GameControls";
import { BaseComponent } from "../../../utils/baseElement";
import { GameBoard } from "../../GameBoard/GameBoard";
import styles from "./Main.module.scss";
import { stateMachine } from "../../../core/StateMachine";
import { ControlsManager } from "../../../core/ControlsManager";

class Main extends BaseComponent {
  /**
   *
   * @param {string} tag
   * @param {string} className
   */
  constructor() {
    super({ tag: "main", className: styles.main });
    this.controlsManager = new ControlsManager(stateMachine);
    this.getNode();
    this.addControls();
    this.addGameBoard();
  }

  addControls() {
    const controls = new GameControls(this.controlsManager);
    this.getNode().append(controls.getNode());
  }

  addGameBoard() {
    const gameBoard = new GameBoard(5, 5);
    this.getNode().append(gameBoard.getNode());
  }
}

export { Main }; //wrapper
